// Read agent context from Data Tables
// This builds the system prompt with soul, memory, and user info

const contextBuilder = {
  buildSystemPrompt: async () => {
    // Get soul (personality)
    const soulData = await $('Read Soul').first().json;
    const soul = {};
    soulData.forEach(row => {
      soul[row.key] = row.value;
    });

    // Get user profile
    const userData = await $('Read User Profile').first().json;
    const user = {};
    userData.forEach(row => {
      user[row.key] = row.value;
    });

    // Get recent memory (last 3 days)
    const recentMemory = await $('Read Recent Memory').first().json;

    // Get relevant long-term memories
    const longTermMemory = await $('Search Long-term Memory').first().json;

    // Build system prompt
    const systemPrompt = `# Agent Identity
Name: ${soul.name || 'Assistant'}
Personality: ${soul.personality || 'Helpful and transparent'}
Communication Style: ${soul.communication_style || 'Clear and conversational'}
Boundaries: ${soul.boundaries || 'Respect privacy and user consent'}

# User Context
Preferred Name: ${user.preferred_name || 'User'}
Timezone: ${user.timezone || 'UTC'}
Communication Preference: ${user.communication_preference || 'balanced'}

# Recent Context
${recentMemory.length ? '## Recent Activity\n' + recentMemory.slice(-5).map(m => `${m.date}: ${m.content}`).join('\n') : 'No recent activity.'}

# Relevant Memories
${longTermMemory.length ? '## Long-term Context\n' + longTermMemory.slice(0, 3).map(m => `[${m.category}] ${m.content}`).join('\n') : 'No relevant long-term memories.'}

# Instructions
You are an AI assistant with transparent behavior. Users can see your workflows on the n8n canvas.
- Be helpful, honest, and direct
- Use available skills/tools when appropriate 
- Remember important information by writing to memory
- Maintain conversation context across sessions
- Respect user boundaries and preferences`;

    return {
      systemPrompt,
      userMessage: $('Chat Hub Trigger').first().json.chatInput,
      conversationId: $('Chat Hub Trigger').first().json.sessionId || 'default'
    };
  }
};

return await contextBuilder.buildSystemPrompt();

// Save conversation summary to daily memory
// This runs after each conversation to maintain context

const saveConversation = () => {
  const agentResponse = $('AI Agent').first().json;
  const userMessage = $('Context Builder').first().json.userMessage;
  const conversationId = $('Context Builder').first().json.conversationId;

  // Create conversation summary
  const summary = `User: ${userMessage}\nAgent: ${agentResponse.output || agentResponse.text || 'No response'}`;

  return {
    date: new Date().toISOString().split('T')[0],
    session_id: conversationId,
    content: summary,
    source: 'chat',
    metadata: {
      timestamp: new Date().toISOString(),
      model: 'claude-3-sonnet', // TODO: get from config
      tokens_used: agentResponse.usage?.total_tokens || 0
    }
  };
};

return saveConversation();
